use rand :: Rng ; struct NeuralNetwork { parameters : Vec < f64 > , arch : Vec < usize > , offsets_w : Vec < usize > , offsets_b : Vec < usize > , } impl NeuralNetwork { fn new (n_par : usize , arch : Vec < usize >) -> Self { let mut rng = rand :: thread_rng () ; let parameters : Vec < f64 > = (0 .. n_par) . map (| _ | rng . gen_range (- 1.0 ..= 1.0)) . collect () ; let n_layer = arch . len () ; let mut offsets_w : Vec < usize > = vec ! [0 ; n_layer] ; let mut offsets_b : Vec < usize > = vec ! [0 ; n_layer] ; offsets_b [0] = arch [1] * arch [0] ; for i in 1 .. n_layer - 1 { offsets_w [i] = arch [i] * offsets_b [i - 1] ; offsets_b [i] = arch [i] * arch [i + 1] + offsets_w [i] ; } NeuralNetwork { parameters , arch , offsets_w , offsets_b , } } fn print_offsets (& self) { let mut it = self . offsets_b . iter () . peekable () ; print ! ("Bias offsets: [") ; while let Some (elem) = it . next () { if it . peek () . is_none () { print ! ("{}" , elem) ; } else { print ! ("{}," , elem) ; } } print ! ("]\n") ; it = self . offsets_w . iter () . peekable () ; print ! ("Bias offsets: [") ; while let Some (elem) = it . next () { if it . peek () . is_none () { print ! ("{}" , elem) ; } else { print ! ("{}," , elem) ; } } print ! ("]\n") ; } } pub fn i_am_alive () { let network = NeuralNetwork :: new (10usize , vec ! [2usize , 25usize , 25usize , 1usize]) ; network . print_offsets () ; }